const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { BatchWriteCommand, DeleteCommand, DynamoDBDocumentClient, GetCommand, PutCommand, QueryCommand } = require('@aws-sdk/lib-dynamodb');
const { ApiGatewayManagementApiClient, PostToConnectionCommand } = require('@aws-sdk/client-apigatewaymanagementapi');
const dynamo = DynamoDBDocumentClient.from(new DynamoDBClient({}));
const tableName = process.env.SESSION_TABLE_NAME;
function parseBody(event) { return event.body ? JSON.parse(event.body) : {}; }
async function listPeers(sessionId, role) { const response = await dynamo.send(new QueryCommand({ TableName: tableName, KeyConditionExpression: 'pk = :pk', ExpressionAttributeValues: { ':pk': `session#${sessionId}` } })); return (response.Items || []).filter((item) => item.role !== role); }
async function postToConnection(domainName, stage, connectionId, payload) { const client = new ApiGatewayManagementApiClient({ endpoint: `https://${domainName}/${stage}` }); await client.send(new PostToConnectionCommand({ ConnectionId: connectionId, Data: Buffer.from(JSON.stringify(payload)) })); }
exports.handler = async (event) => { const routeKey = event.requestContext.routeKey; const connectionId = event.requestContext.connectionId; const domainName = event.requestContext.domainName; const stage = event.requestContext.stage; const requestBody = parseBody(event); let sessionId = event.queryStringParameters?.sessionId || requestBody.sessionId; let role = event.queryStringParameters?.role || requestBody.role || 'unknown'; if (routeKey === '$connect') { if (!sessionId) { return { statusCode: 400, body: 'sessionId is required' }; } await dynamo.send(new BatchWriteCommand({ RequestItems: { [tableName]: [{ PutRequest: { Item: { pk: `session#${sessionId}`, sk: `connection#${connectionId}`, connectionId, role } } }, { PutRequest: { Item: { pk: `connection#${connectionId}`, sk: 'meta', sessionId, role } } }] } })); return { statusCode: 200, body: JSON.stringify({ ok: true, stunServerUrl: process.env.STUN_SERVER_URL }) }; } if (routeKey === '$disconnect') { const connectionRecord = await dynamo.send(new GetCommand({ TableName: tableName, Key: { pk: `connection#${connectionId}`, sk: 'meta' } })); if (!connectionRecord.Item?.sessionId) { return { statusCode: 200, body: JSON.stringify({ ok: true, removed: false }) }; } sessionId = connectionRecord.Item.sessionId; await dynamo.send(new BatchWriteCommand({ RequestItems: { [tableName]: [{ DeleteRequest: { Key: { pk: `session#${sessionId}`, sk: `connection#${connectionId}` } } }, { DeleteRequest: { Key: { pk: `connection#${connectionId}`, sk: 'meta' } } }] } })); return { statusCode: 200, body: JSON.stringify({ ok: true, removed: true }) }; } if (!sessionId) { return { statusCode: 400, body: 'sessionId is required' }; } const peers = await listPeers(sessionId, role); await Promise.all(peers.map((peer) => postToConnection(domainName, stage, peer.connectionId, requestBody))); return { statusCode: 200, body: JSON.stringify({ delivered: peers.length }) }; };
